/**
 * The generator: neutral template source -> agent-specific files.
 *
 * Reads templates/skills + templates/commands, substitutes {{AIDLC_ROOT}} for each
 * agent's path dialect, and writes the files into each selected agent's location.
 * Every generated file carries a "generated by nvaid — do not edit" header so the
 * clobber contract (proposal §10.3 / §14.3) is visible in the file itself.
 */
import { readFile, writeFile, mkdir, readdir, rm } from "node:fs/promises";
import { existsSync } from "node:fs";
import { join, relative } from "node:path";
import type { AgentTarget } from "./agents.js";
import { SKILLS_SRC, COMMANDS_SRC, AIDLC_ROOT_TOKEN } from "./paths.js";
import { withHeader } from "./header.js";

export interface GenerateOptions {
  projectRoot: string;
  agents: AgentTarget[];
  /** overwrite existing generated files (update) vs. skip existing (init) */
  force: boolean;
}

export interface GenerateResult {
  written: string[];
  skipped: string[];
}

/** Where {{AIDLC_ROOT}} resolves to, from a generated file's own directory. */
function aidlcRootFor(agent: AgentTarget): string {
  // All agents read the shared rules from the repo-local nvaid/ folder.
  // Skills reference e.g. {{AIDLC_ROOT}}/unit-breakdown-rules.md; point them at nvaid/rules.
  void agent;
  return "nvaid/rules";
}

async function listSkillDirs(): Promise<string[]> {
  const entries = await readdir(SKILLS_SRC, { withFileTypes: true });
  return entries.filter((e) => e.isDirectory()).map((e) => e.name);
}

async function listCommandFiles(): Promise<string[]> {
  const entries = await readdir(COMMANDS_SRC, { withFileTypes: true });
  return entries.filter((e) => e.isFile() && e.name.endsWith(".md")).map((e) => e.name);
}

/** Resolve the template body: read, substitute the AIDLC_ROOT token, add the header. */
async function renderTemplate(srcFile: string, agent: AgentTarget): Promise<string> {
  const raw = await readFile(srcFile, "utf8");
  const substituted = raw.split(AIDLC_ROOT_TOKEN).join(aidlcRootFor(agent));
  return withHeader(substituted);
}

/**
 * Target path for one skill under a given agent. Every agent uses the Agent Skills
 * layout: a directory per skill containing SKILL.md, folder name == frontmatter `name`.
 */
function skillTarget(projectRoot: string, agent: AgentTarget, skill: string): string {
  return join(projectRoot, agent.skillsPath, skill, "SKILL.md");
}

function commandTarget(projectRoot: string, agent: AgentTarget, cmdFile: string): string {
  const base = cmdFile.replace(/\.md$/, "");
  if (agent.commandsPath) {
    // Dedicated command system: write under <commandsPath>/nvaid/<name> so the agent
    // invokes it as `/nvaid:<name>` (the subdir provides the namespace).
    return join(projectRoot, agent.commandsPath, "nvaid", `${base}.md`);
  }
  // No separate command system: emit the command as an invocable skill (a command is just
  // a skill under the Agent Skills model), reachable as /nvaid-<name>.
  return join(projectRoot, agent.skillsPath, `nvaid-${base}`, "SKILL.md");
}

async function writeFileEnsuringDir(path: string, body: string, force: boolean, result: GenerateResult): Promise<void> {
  if (!force && existsSync(path)) {
    result.skipped.push(path);
    return;
  }
  await mkdir(join(path, ".."), { recursive: true });
  await writeFile(path, body, "utf8");
  result.written.push(path);
}

/** Write skills + command defs into every selected agent's location. */
export async function generateAgentFiles(opts: GenerateOptions): Promise<GenerateResult> {
  const result: GenerateResult = { written: [], skipped: [] };
  const skills = await listSkillDirs();
  const commands = await listCommandFiles();

  for (const agent of opts.agents) {
    // skills
    for (const skill of skills) {
      const src = join(SKILLS_SRC, skill, "SKILL.md");
      if (!existsSync(src)) continue;
      const body = await renderTemplate(src, agent);
      await writeFileEnsuringDir(skillTarget(opts.projectRoot, agent, skill), body, opts.force, result);
    }
    // commands
    for (const cmd of commands) {
      const body = await renderTemplate(join(COMMANDS_SRC, cmd), agent);
      await writeFileEnsuringDir(commandTarget(opts.projectRoot, agent, cmd), body, opts.force, result);
    }
  }
  return result;
}

/**
 * Compare on-disk generated files against freshly generated output (nvaid validate).
 * Returns the list of files that are missing, stale, or hand-edited.
 */
export async function diffAgentFiles(opts: GenerateOptions): Promise<string[]> {
  const drift: string[] = [];
  const skills = await listSkillDirs();
  const commands = await listCommandFiles();

  // Carry the agent alongside each check so rendering uses the right format/paths —
  // don't infer the agent back from the target path (command targets live under
  // commandsPath, not skillsPath, so a path-substring match would be wrong).
  const checks: Array<{ target: string; src: string; agent: AgentTarget }> = [];
  for (const agent of opts.agents) {
    for (const skill of skills) {
      const src = join(SKILLS_SRC, skill, "SKILL.md");
      if (existsSync(src)) checks.push({ target: skillTarget(opts.projectRoot, agent, skill), src, agent });
    }
    for (const cmd of commands) {
      checks.push({ target: commandTarget(opts.projectRoot, agent, cmd), src: join(COMMANDS_SRC, cmd), agent });
    }
  }

  for (const { target, src, agent } of checks) {
    const expected = await renderTemplate(src, agent);
    if (!existsSync(target)) {
      drift.push(`${relative(opts.projectRoot, target)} (missing)`);
      continue;
    }
    const actual = await readFile(target, "utf8");
    if (actual !== expected) drift.push(relative(opts.projectRoot, target));
  }
  return drift;
}

/**
 * Remove previously generated nvaid files for a clean regenerate (used by update).
 * Sweeps the current command dir AND legacy locations from older nvaid versions, so an
 * upgrade cleans up files whose layout changed (e.g. the old .claude/skills/commands/
 * copies, or flat skill files left behind when a skill moves to <name>/SKILL.md).
 */
export async function cleanAgentDirs(projectRoot: string, agents: AgentTarget[]): Promise<void> {
  const skills = await listSkillDirs().catch(() => [] as string[]);

  for (const agent of agents) {
    // 1. current command dir (dedicated command system) — nvaid-owned, safe to remove
    if (agent.commandsPath) {
      await rmIfExists(join(projectRoot, agent.commandsPath, "nvaid"));
    }
    // 2. legacy command locations from older nvaid versions
    await rmIfExists(join(projectRoot, agent.skillsPath, "commands"));
    await rmIfExists(join(projectRoot, agent.skillsPath, "nvaid-commands"));

    // 3. stale flat skill files from the pre-dir-layout versions (<name>.md / .mdc)
    for (const skill of skills) {
      await rmIfExists(join(projectRoot, agent.skillsPath, `${skill}.md`));
      await rmIfExists(join(projectRoot, agent.skillsPath, `${skill}.mdc`));
    }
  }
}

async function rmIfExists(path: string): Promise<void> {
  if (existsSync(path)) await rm(path, { recursive: true, force: true });
}
